brow">A dark fantasy of memory and mortality</div><h1>The Parish of Hollow Ash</h1><p>Death is final here. Except, somehow, for you.</p></div><div class="chapter-pill">THE ASHEN MARCH &nbsp;·&nbsp; PROLOGUE</div></section>
    <div class="layout">
      <section class="game-card" aria-label="Game world"><div class="screen-head"><div class="loc"><i class="loc-mark"></i><span>HOLLOW ASH PARISH</span></div><span class="time" id="world-time">DUSK · COLD RAIN</span></div><div class="viewport"><canvas id="game" width="480" height="270" aria-label="Top-down pixel art view of Hollow Ash Parish. Use arrow keys or WASD to walk around."></canvas><div class="canvas-vignette"></div><div class="collapse-wash" id="collapse-wash"></div><div class="dream-shatter" id="dream-shatter"></div><button class="system-trigger" id="system-trigger" type="button">System</button><div id="toast" class="toast" role="status"></div><div class="dream-tag" id="dream-tag" style="display: none;">THE PLACE BETWEEN BREATHS</div><div class="dream-dialogue" id="dream-dialogue" role="button" tabindex="0" aria-label="Continue conversation"><div class="dialogue-head"><span id="dialogue-name">MEDIA</span></div><div class="dialogue-text" id="dialogue-text"></div><div class="dialogue-hint">E / SPACE · CONTINUE</div></div><div class="touch-controls" aria-label="Touch movement controls"><div class="dpad"><button class="touch-btn up" data-dir="up" aria-label="Move up">▲</button><button class="touch-btn left" data-dir="left" aria-label="Move left">◀</button><button class="touch-btn down" data-dir="down" aria-label="Move down">▼</button><button class="touch-btn right" data-dir="right" aria-label="Move right">▶</button></div><button class="action-touch" id="touch-action" aria-label="Interact">ACT</button></div></div><div class="game-footer"><div class="objective"><span class="star">✦</span><span id="objective-text">Recover three death-tolls for the chapel bell</span></div><div class="key-help"><span class="keycap">W</span><span class="keycap">A</span><span class="keycap">S</span><span class="keycap">D</span><span style="margin-left:5px">move</span><span class="keycap" style="margin-left:6px">E</span><span>interact</span></div></div></section>
      <aside class="side">
        <section class="side-card"><div class="card-kicker" id="quest-kicker">A debt unpaid</div><h2 id="quest-title">The Bell's Last Toll</h2><p id="quest-description">Three iron death-tolls lie among the graves. Bring them to the ruined chapel. The gravedigger says nothing of why its bell still rings.</p><div class="quest-row"><span id="quest-label">Death-tolls recovered</span><span class="quest-count" id="toll-count">0 / 3</span></div><div class="meter"><span id="toll-meter" style="width: 0%;"></span></div></section>
        <section class="side-card steps-card"><div class="card-kicker">Roadmap · the world to come</div><ul class="step-list" id="step-list"><li class="step current"><span class="step-num">01</span><div class="step-copy"><div class="step-title">Hollow Ash Parish</div><div class="step-note">A ruined chapel, a nameless traveler, and the bell that tolls for no one.</div></div></li><li class="step "><span class="step-num">02</span><div class="step-copy"><div class="step-title">The road to Veyr</div><div class="step-note">A starving village beneath the church’s shadow; every soul has a price.</div></div></li><li class="step "><span class="step-num">03</span><div class="step-copy"><div class="step-title">The buried kingdom</div><div class="step-note">Crypts, censored histories, and the traces of a vanished civilization.</div></div></li><li class="step "><span class="step-num">04</span><div class="step-copy"><div class="step-title">The deathless hour</div><div class="step-note">Discover why the world returns with you—and what each return costs.</div></div></li></ul></section>
        <section class="side-card controls-card"><div class="card-kicker">Survival &amp; controls <button class="edit-btn" id="edit-steps" aria-label="Edit roadmap" title="Edit roadmap" style="float:right;margin-top:-7px"><svg viewBox="0 0 24 24" fill="none"><path d="m14 5 5 5M4 20l4.3-.9L19 8.4a2.1 2.1 0 0 0-3-3L5.3 16.1 4 20Z" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"></path></svg></button></div><div class="controls-row"><span>Walk around</span><span>WASD / arrows</span></div><div class="controls-row"><span>Speak / gather</span><span>E / SPACE</span></div></section>
      </aside>
    </div>
    <div class="footer-note">A WORLD THAT REMEMBERS &nbsp;·&nbsp; YOUR JOURNEY SAVES ON THIS DEVICE</div>
  </main>
  <div class="system-backdrop" id="system-backdrop" role="dialog" aria-modal="true" aria-labelledby="system-title"><section class="system-window"><header class="system-head"><div><div class="system-overline">Divine Authority · Fragment 01</div><h2 id="system-title">The Soulbound Window</h2></div><button class="system-close" id="system-close" aria-label="Close System">✕</button></header><p class="system-subtitle">SUBJECT: THE CALLED · FORM: HUMAN SOUL · STATUS: INCARNATION PENDING</p><div class="system-grid"><section class="system-pane"><h3>Condition</h3><div class="stat-row"><span>Level</span><b>01 · Unawakened</b></div><div class="stat-row"><span>Vitality</span><b>12 / 12</b></div><div class="stat-row"><span>Resolve</span><b>08 / 08</b></div><div class="stat-row"><span>Strength</span><b>03</b></div><div class="stat-row"><span>Endurance</span><b>04</b></div><div class="stat-row"><span>Perception</span><b>05</b></div><div class="stat-row"><span>Experience</span><b>0 / 100</b></div></section><section class="system-pane"><h3>Abilities &amp; Gifts</h3><div class="system-skill"><strong>Deathless Return <span style="color:#c6a665;font:9px var(--mono)">· DORMANT</span></strong><p>Upon death, time will regress to your point of arrival. Memory persists where the body cannot.</p></div><div class="system-skill"><strong>Untrained</strong><p>No combat disciplines or proficiencies have been awakened.</p></div><div class="system-skill"><strong>Media's Covenant</strong><p>A faint bond connects your fate to a fading divine presence.</p></div></section></div><p class="system-foot">A GIFT OF MEDIA · THIS WINDOW ANSWERS WHEN CALLED</p></section></div><div class="dream-ending" id="dream-ending"></div>
  <div class="modal-backdrop" id="roadmap-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal"><div class="modal-head"><div><h2 id="modal-title">Shape the journey</h2><p class="hint">Edit the roadmap as we build. Your notes stay on this device.</p></div><button class="close-btn" id="close-modal" aria-label="Close">✕</button></div><div id="edit-rows"></div><div class="modal-actions"><button class="reset-btn" id="reset-roadmap">Reset roadmap</button><small>Changes save automatically when applied.</small><button class="primary-btn" id="save-roadmap">Save changes</button></div></div></div>
  <script>
  const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
  const W=480,H=270,T=20,MAP_W=44,MAP_H=36,MW=MAP_W*T,MH=MAP_H*T;
  const keys=new Set();let last=0,toastTimer=0,walkPhase=0,stepData,dialogueOpen=false,dialogueIndex=0,dreamReturn=null,gameStarted=false,openingAt=0,collapseStartedAt=0,continueAt=0,transportAt=0,transportFinishAt=0,dreamCollapse=0;
  const defaultSteps=[
    {title:'Hollow Ash Parish',note:'A ruined chapel, a nameless traveler, and the bell that tolls for no one.',status:'current'},
    {title:'The road to Veyr',note:'A starving village beneath the church’s shadow; every soul has a price.',status:'next'},
    {title:'The buried kingdom',note:'Crypts, censored histories, and the traces of a vanished civilization.',status:'next'},
    {title:'The deathless hour',note:'Discover why the world returns with you—and what each return costs.',status:'next'}
  ];
  const state={x:430,y:355,face:'down',tolls:[],bellAnswered:false,scene:'parish',memories:[],deaths:0,wraith:{x:240,y:55},elapsed:0,cellItems:false,cellWall:false,cellStraw:false,cellBars:false,cellDoor:false,cellTalk:0,systemUnlocked:false};
  let activeLines=[],dialogueKind='';
  const keySave='agrippina-save-v1',roadmapSave='agrippina-roadmap-v1';
  let audioCtx=null,ambienceStarted=false,lastDripAt=0,mediaThemeTimer=0,cellDroneGain=null,cellNoiseGain=null;
  function startAudio(){if(audioCtx){audioCtx.resume();return}const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioCtx=new AC();audioCtx.resume();}
  function tone(freq,duration,volume=.025,type='sine',when=0){if(!audioCtx)return;const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.0001,audioCtx.currentTime+when);gain.gain.exponentialRampToValueAtTime(volume,audioCtx.currentTime+when+.08);gain.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+when+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start(audioCtx.currentTime+when);osc.stop(audioCtx.currentTime+when+duration+.03)}
  function startMediaTheme(){if(!audioCtx||state.scene!=='dream')return;clearInterval(mediaThemeTimer);const notes=[261.63,329.63,392,329.63,293.66,349.23,440,392];let i=0;const phrase=()=>{if(state.scene!=='dream'){clearInterval(mediaThemeTimer);mediaThemeTimer=0;return}const t=i*1.1;tone(notes[i%notes.length],2.1,.018,'triangle',t);tone(notes[i%notes.length]/2,2.4,.012,'sine',t);if(i%4===0)tone(notes[(i+2)%notes.length]*1.5,2.8,.006,'sine',t+.22);i++};phrase();mediaThemeTimer=setInterval(phrase,8800)}
  function stopMediaTheme(){clearInterval(mediaThemeTimer);mediaThemeTimer=0}
  function startCellAmbience(){if(!audioCtx)return;if(!ambienceStarted){ambienceStarted=true;const osc=audioCtx.createOscillator(),gain=audioCtx.createGain(),filter=audioCtx.createBiquadFilter();osc.type='sine';osc.frequency.value=43;filter.type='lowpass';filter.frequency.value=100;gain.gain.value=.0001;cellDroneGain=gain;osc.connect(filter);filter.connect(gain);gain.connect(audioCtx.destination);osc.start();const size=audioCtx.sampleRate*2,buffer=audioCtx.createBuffer(1,size,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<size;i++)data[i]=(Math.random()*2-1)*.12;const noise=audioCtx.createBufferSource(),ng=audioCtx.createGain(),nf=audioCtx.createBiquadFilter();noise.buffer=buffer;noise.loop=true;nf.type='lowpass';nf.frequency.value=380;ng.gain.value=.0001;cellNoiseGain=ng;noise.connect(nf);nf.connect(ng);ng.connect(audioCtx.destination);noise.start()}const now=audioCtx.currentTime;if(cellDroneGain)cellDroneGain.gain.setTargetAtTime(state.scene==='cell'?.025:.0001,now,.8);if(cellNoiseGain)cellNoiseGain.gain.setTargetAtTime(state.scene==='cell'?.07:.0001,now,.8)}
  function setAudioScene(){if(state.scene==='dream'){startCellAmbience();startMediaTheme()}else{stopMediaTheme();if(ambienceStarted)startCellAmbience()}}
  function drip(now){if(!audioCtx||state.scene!=='cell'||now-lastDripAt<3900)return;lastDripAt=now;tone(570,.16,.012,'sine');tone(188,.42,.009,'sine',.17)}
  const deathTolls=[{x:358,y:278},{x:540,y:300},{x:625,y:423}];
  const trees=[
    [65,90,1.05],[120,300,.85],[280,82,.85],[340,120,.72],[590,86,1.0],[775,110,1.1],[820,290,.8],[720,390,1.1],[630,520,.9],[390,530,1.1],[180,470,1.0],[70,575,.85],[845,540,.95],[315,390,.7],[570,470,.75],[95,205,.7],[760,220,.75],[265,255,.65]
  ];
  let seed=8731;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
  function load(){try{const s=JSON.parse(localStorage.getItem(keySave)||'null');if(s){state.x=Number.isFinite(s.x)?s.x:state.x;state.y=Number.isFinite(s.y)?s.y:state.y;state.tolls=Array.isArray(s.tolls)?s.tolls:[];state.bellAnswered=!!s.bellAnswered;state.memories=Array.isArray(s.memories)?s.memories:[];state.deaths=Number.isFinite(s.deaths)?s.deaths:0;state.cellItems=!!s.cellItems;state.cellWall=!!s.cellWall;state.cellStraw=!!s.cellStraw;state.cellBars=!!s.cellBars;state.cellDoor=!!s.cellDoor;state.cellTalk=Number.isFinite(s.cellTalk)?s.cellTalk:0;state.systemUnlocked=!!s.systemUnlocked;state.scene=['cell','crypt'].includes(s.scene)?s.scene:'parish';if(state.scene==='crypt'&&!state.bellAnswered)state.scene='parish';if(state.scene==='crypt'){state.x=Number.isFinite(s.x)?s.x:240;state.y=Number.isFinite(s.y)?s.y:220;state.wraith=s.wraith||state.wraith}if(state.scene==='cell'){state.x=Number.isFinite(s.x)?s.x:240;state.y=Number.isFinite(s.y)?s.y:207}}}catch{}try{const saved=JSON.parse(localStorage.getItem(roadmapSave)||'null');stepData=Array.isArray(saved)&&saved.length===4?saved:structuredClone(defaultSteps)}catch{stepData=structuredClone(defaultSteps)}}
  function save(){try{localStorage.setItem(keySave,JSON.stringify({x:state.x,y:state.y,tolls:state.tolls,bellAnswered:state.bellAnswered,scene:state.scene,memories:state.memories,deaths:state.deaths,wraith:state.wraith,cellItems:state.cellItems,cellWall:state.cellWall,cellStraw:state.cellStraw,cellBars:state.cellBars,cellDoor:state.cellDoor,cellTalk:state.cellTalk,systemUnlocked:state.systemUnlocked}))}catch{}}
  function saveRoadmap(){try{localStorage.setItem(roadmapSave,JSON.stringify(stepData))}catch{}}
  function drawGrass(){seed=8731;for(let y=0;y<MAP_H;y++)for(let x=0;x<MAP_W;x++){let r=rand(),px=x*T,py=y*T;ctx.fillStyle=r>.83?'#55534f':r>.55?'#4c4d49':r>.22?'#51524d':'#585750';ctx.fillRect(px,py,T,T);if(r>.48){ctx.fillStyle=r>.72?'#69645a':'#424743';ctx.fillRect(px+Math.floor(rand()*17)+1,py+Math.floor(rand()*16)+2,2,2)}if(r<.12){ctx.fillStyle='#777064';ctx.fillRect(px+4,py+14,1,3);ctx.fillRect(px+6,py+12,1,5)}}
    // Mud-churned tracks between a ruined chapel and its abandoned grounds.
    const path=(x,y,w,h)=>{ctx.fillStyle='#393536';ctx.fillRect(x,y,w,h);ctx.fillStyle='#484140';ctx.fillRect(x+2,y+2,w-4,h-4);for(let i=0;i<Math.floor(w*h/210);i++){ctx.fillStyle=i%2?'#302e30':'#62564b';ctx.fillRect(x+3+rand()*(w-6),y+3+rand()*(h-6),2,1)}};
    path(418,255,37,160);path(421,255,165,30);path(585,163,26,125);path(585,164,104,27);path(451,378,164,23);
    // A stagnant tarn, stained dark by peat and old ash.
    ctx.fillStyle='#393637';ctx.beginPath();ctx.ellipse(194,192,99,70,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#575149';ctx.beginPath();ctx.ellipse(194,189,92,64,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#303b3a';ctx.beginPath();ctx.ellipse(194,184,81,53,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#394542';ctx.beginPath();ctx.ellipse(194,181,70,44,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#858175';[[160,164,12,1],[218,183,16,1],[176,201,9,1],[231,169,7,1]].forEach(a=>ctx.fillRect(...a));
