  function tone(freq,duration,volume=.025,type='sine',when=0){if(!audioCtx)return;const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.0001,audioCtx.currentTime+when);gain.gain.exponentialRampToValueAtTime(volume,audioCtx.currentTime+when+.08);gain.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+when+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start(audioCtx.currentTime+when);osc.stop(audioCtx.currentTime+when+duration+.03)}
